<script setup lang="ts">
import {computed} from "vue";
import type {Permission} from "../lib/types";
import {permissionGroups} from "../lib/content";
const props=defineProps<{modelValue:string[];permissions:Permission[];delegable:string[];search:string;selectedOnly:boolean}>();
const emit=defineEmits<{"update:modelValue":[value:string[]]}>();
const allowed=(p:Permission)=>props.delegable.includes(p.id)&&!p.owner_only;
const basePermissions=new Set(["profile.edit","saves.read","saves.write","stats.read_own","telemetry.create"]);
const matches=(p:Permission)=>!basePermissions.has(p.id)&&!p.legacy&&(!props.selectedOnly||props.modelValue.includes(p.id))&&(!props.search||(p.title+' '+p.id+' '+(p.description||'')).toLocaleLowerCase('ru').includes(props.search.toLocaleLowerCase('ru')));
const rows=[{label:'Редактирование',own:'projects.edit',all:'projects.edit_any'},{label:'Публикация и скрытие',own:'projects.publish',all:'projects.publish_any'},{label:'Участники',own:'projects.assign_assigned',all:'projects.assign'},{label:'Удаление и восстановление',own:'projects.delete',all:'projects.delete_any'}];
const projectRows=computed(()=>rows.map(r=>({...r,permissions:[r.own,r.all].map(id=>props.permissions.find(p=>p.id===id))})).filter(r=>r.permissions.some(p=>p&&matches(p))));
const groups=computed(()=>{const g:Record<string,Permission[]>={};for(const p of props.permissions){if(matches(p)&&!rows.some(r=>r.own===p.id||r.all===p.id))(g[p.group]??=[]).push(p);}return Object.entries(g)});
function toggle(p:Permission,checked:boolean){if(!allowed(p))return;emit('update:modelValue',checked?[...new Set([...props.modelValue,p.id])]:props.modelValue.filter(id=>id!==p.id));}
</script>
<template><p class="field-note">Базовые возможности аккаунта доступны всем и не задаются ролью.</p><section v-if="projectRows.length" class="permission-group"><h4>Проекты: действие и область</h4><p class="field-note">Доверенные — проекты, куда человека назначили разработчиком, или выдали личный допуск. «Все» включает доверенные проекты. Тестировщик не получает управление автоматически.</p><table class="scope-table"><thead><tr><th>Действие</th><th>Доверенные</th><th>Все</th></tr></thead><tbody><tr v-for="row in projectRows" :key="row.own"><th>{{row.label}}</th><td v-for="(p,index) in row.permissions" :key="index"><label v-if="p" :class="{disabled:!allowed(p)}"><input type="checkbox" :checked="modelValue.includes(p.id)" :disabled="!allowed(p)" :aria-label="row.label+' · '+(index?'все проекты':'доверенные проекты')" @change="toggle(p,($event.target as HTMLInputElement).checked)"/></label></td></tr></tbody></table></section><section v-for="[group,items] in groups" :key="group" class="permission-group"><h4>{{permissionGroups[group]||group}}</h4><p v-if="group==='account_notes'" class="field-note">Видимость: автор заметки, Admin и Owner. Просмотр не даёт права править или удалять. Права на чужие заметки работают только у Admin; заметки Owner защищены от чужих изменений.</p><div class="permission-grid"><label v-for="p in items" :key="p.id" class="permission-option" :class="{disabled:!allowed(p)}"><input type="checkbox" :checked="modelValue.includes(p.id)" :disabled="!allowed(p)" @change="toggle(p,($event.target as HTMLInputElement).checked)"/><span>{{p.title}}<small v-if="p.owner_only">Закреплено за Owner</small><small v-else-if="!allowed(p)">Выдаёт только Owner</small><small v-else-if="p.description&&group!=='account_notes'">{{p.description}}</small></span></label></div></section><p v-if="modelValue.some(p=>p.startsWith('account_notes.'))&&!modelValue.includes('users.read')" class="notice">Для работы с заметками также нужно право «Просматривать карточки аккаунтов».</p></template>
